import React, { useEffect } from 'react'
import './Zambrug.css'

const ZamZoom = () => {

  useEffect(() => {
    function imageZoom(imgID, resultID) {
      var img, lens, result, cx, cy;
      img = document.getElementById(imgID);
      result = document.getElementById(resultID);
      if (!img || !result) return;

      lens = document.createElement("DIV");
      lens.setAttribute("class", "img-zoom-lens");
      img.parentElement.insertBefore(lens, img);

      cx = result.offsetWidth / lens.offsetWidth;
      cy = result.offsetHeight / lens.offsetHeight;

      result.style.backgroundImage = "url('" + img.src + "')";
      result.style.backgroundSize = (img.width * cx) + "px " + (img.height * cy) + "px";

      lens.addEventListener("mousemove", moveLens);
      img.addEventListener("mousemove", moveLens);
      lens.addEventListener("touchmove", moveLens);
      img.addEventListener("touchmove", moveLens);

      function moveLens(e) {
        e.preventDefault();
        let pos = getCursorPos(e);
        let x = pos.x - lens.offsetWidth / 2;
        let y = pos.y - lens.offsetHeight / 2;

        if (x > img.width - lens.offsetWidth) x = img.width - lens.offsetWidth;
        if (x < 0) x = 0;
        if (y > img.height - lens.offsetHeight) y = img.height - lens.offsetHeight;
        if (y < 0) y = 0;

        lens.style.left = x + "px";
        lens.style.top = y + "px";
        result.style.backgroundPosition =
          "-" + x * cx + "px -" + y * cy + "px";
      }

      function getCursorPos(e) {
        e = e || window.event;
        let a = img.getBoundingClientRect();
        let x = e.pageX - a.left - window.pageXOffset;
        let y = e.pageY - a.top - window.pageYOffset;
        return { x, y };
      }
    }

    // DOM tayyor bo'lgandan keyin zoom ishlaydi
    imageZoom("myimage", "myresult");

  }, []);

  return (
    <div className='zamzoom'>
      <div className="pages-title zambrug">
        <h1>Zamburug' hujayrasining tuzilishini mikroskop ostida kuzatish</h1>

      </div>

      <div className="main_cont">
        <div className="img-zoom-container">
          <img id="myimage" src="/images/salom.jpg" width="250" height="300" alt="Girl" />
          <div id="myresult" className="img-zoom-result"></div>
        </div>
      </div>
    </div>
  )
}

export default ZamZoom;
